#define wmain OriginalInterpolationReferenceMain
#include "InterpolationReference.cpp"
#undef wmain
int wmain(int argc,wchar_t** argv){try{if(argc!=3)throw std::runtime_error("input/output required");GdiplusStartupInput input;ULONG_PTR token=0;ok(GdiplusStartup(&token,&input,nullptr),"startup");{fs::path source(argv[1]),out(argv[2]);fs::create_directories(out);std::ofstream report(out/"pixel-alias-observations.json");report<<"{\"cases\":[";int count=0;for(bool alpha:{false,true})for(int mode:{3,5})for(const char* scene:{"integer","quarter","half","three-quarter","negative","reflection","affine","crop"}){auto name=std::string(alpha?"alpha":"opaque")+"-i"+std::to_string(mode)+"-p4-"+scene;std::ifstream f(source/(name+".emf"),std::ios::binary);Bytes bytes((std::istreambuf_iterator<char>(f)),{});if(bytes.size()>65536)throw std::runtime_error("wire budget");int changed=0;for(size_t p=0;p+8<=bytes.size();){DWORD size=u32(bytes,p+4);if(size<8||size>bytes.size()-p)throw std::runtime_error("EMF bounds");if(u32(bytes,p)==70&&size>=16&&u32(bytes,p+12)==0x2b464d45){size_t end=p+12+u32(bytes,p+8);for(size_t q=p+16;q+12<=end;){DWORD n=u32(bytes,q+4);if(n<12||n>end-q)throw std::runtime_error("plus bounds");if(u16(bytes,q)==0x4022){if(u16(bytes,q+2)!=4)throw std::runtime_error("native Half expected");bytes[q+2]=2;changed++;}q+=n;}}p+=size;}if(changed!=1)throw std::runtime_error("one Half record expected");auto id=name+"-pixel2";write(out/(id+".emf"),bytes);records(out/(id+".emf"),out/(id+"-records.json"));write(out/(id+"-natural.rgba"),replay(out/(id+".emf"),false));write(out/(id+"-picture.rgba"),replay(out/(id+".emf"),true));if(count++)report<<",";report<<"{\"name\":\""<<id<<"\",\"source\":\""<<name<<"\"}";}report<<"],\"completedCaseCount\":"<<count<<"}";std::cout<<"Captured "<<count<<" raw pixel aliases\n";}GdiplusShutdown(token);return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
